control_codes.count_only:
def solve(data):
    ids = data['task_ids']
    wanted = set(ids)
    if not ids or len(wanted) != len(ids):
        raise ValueError('invalid_task_ids')
    summaries = {}
    usable_sets = {}
    for side in ['baseline', 'candidate']:
        rows = data[side]
        observed = [row['task_id'] for row in rows]
        if len(observed) != len(ids) or set(observed) != wanted:
            raise ValueError('invalid_coverage')
        usable = []
        unusable = []
        total = 0
        for row in rows:
            total = total + row['elapsed_ms']
            if row['status'] == 'usable':
                usable.append(row['task_id'])
            else:
                unusable.append(row['task_id'])
        summaries[side] = {'attempted': len(rows), 'usable': len(usable), 'unusable_ids': sorted(unusable), 'total_elapsed_ms': total}
        usable_sets[side] = set(usable)
    before = usable_sets['baseline']
    after = usable_sets['candidate']
    before_ms = summaries['baseline']['total_elapsed_ms']
    after_ms = summaries['candidate']['total_elapsed_ms']
    retained = len(after) >= len(before)
    accepted = bool(after) and retained and after_ms <= before_ms and (len(after) > len(before) or after_ms < before_ms)
    return {'decision': 'accept' if accepted else 'reject', 'baseline': summaries['baseline'], 'candidate': summaries['candidate']}

